const modules = [
  {week:1,title:"The Therapist Behind the Therapy",outcome:"Understand What Is Actually Getting in Your Way.",lessons:["Confidence Is Not a Personality Trait","Meet the Clinician Behind the Reaction","Use P.A.U.S.E. When You Go Blank"],demo:"When the Client Asks You to Decide for Them",cases:["The Advice Request","The Long Silence"],tool:"Clinical Confidence Profile"},
  {week:2,title:"Getting Unstuck in the Room",outcome:"Know How to Choose Your Next Move.",lessons:["Find the Thread, Not Just the Topic","CLEAR: A Clinical Thinking Cycle","Choose a Move You Can Explain"],demo:"Four Topics, One Thread",cases:["Everything at Once","The Reassurance Loop"],tool:"Clinical Decision-Making Map"},
  {week:3,title:"From Conversation to Clinical Movement",outcome:"Guide the Session With Purpose.",lessons:["Begin With a Destination, Not a Script","Deepen or Shift? The Mid-Session Choice","The Last Ten Minutes Still Matter"],demo:"How to Guide Without Steamrolling",cases:["A Connected but Wandering Session","Five Minutes Left"],tool:"50-Minute Session Roadmap"},
  {week:4,title:"Become a Clinician You Can Trust",outcome:"Reflect, Repair, and Keep Developing.",lessons:["Debrief the Choice, Not Your Worth","When Your Response Misses","Build Confidence From Evidence"],demo:"What to Do When Your Response Misses",cases:["The Missed Connection","The Plateau"],tool:"Personal Clinical Playbook + 30-Day Plan"},
];

const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v="")=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let completed=new Set(JSON.parse(sessionStorage.getItem('tccLabPreviewProgress')||'[]')); let caseStep=1; let blindSpotRound=1; let simulationNode="J00"; let profileTab="snapshot"; const caseAnswers={}; const blindSpotAnswers={}; const simulationHistory=[];
const screenHistory=[];
const profileState={focus:new Set(),pressure:new Set(),cues:new Set(),attention:new Set(),resets:new Set(),strengths:new Set(),protecting:"",impact:"",exception:"",target:"",independent:"",support:"",supervision:"",evidence:[]};
const PREVIEW_SESSION="tccLabStudentPreview";
const PREVIEW_EMAIL="studentpreview@theconfidentclinician.me";
const PREVIEW_PASSWORD="LabPreview2026!";
const OVERRIDE_KEY="tccLabCreatorOverride";
let creatorOverride=sessionStorage.getItem(OVERRIDE_KEY)==='1';
let pendingGate=null;
const gateRequirements={"blind-spot":"start","simulation-room":"blind","case-advice":"blind","profile":"simulation"};
const saveProgress=()=>sessionStorage.setItem('tccLabPreviewProgress',JSON.stringify([...completed]));
const markComplete=(key)=>{completed.add(key);saveProgress();renderModules();refreshGateUI()};
const accessReason=(name)=>{if(creatorOverride)return'';if(/^week-[2-4]$/.test(name))return`${name.replace('week-','Week ')} opens on its scheduled release date after the previous week’s essential activities are complete.`;const requirement=gateRequirements[name];if(requirement&&!completed.has(requirement))return requirement==='start'?'Complete and save the starting reflection first.':requirement==='blind'?'Complete the Clinical Blind Spot Lab first.':'Complete the Week 1 simulation first.';return''};
const openGate=(target,message)=>{pendingGate=target;const dialog=$('[data-gate-dialog]');$('[data-gate-title]').textContent='This content is not open yet.';$('[data-gate-message]').textContent=message;$('[data-gate-error]').textContent='';dialog.showModal()};
const setPreviewAccess=(allowed)=>{document.body.classList.toggle("preview-authenticated",allowed);$("[data-preview-login]").hidden=allowed;if(allowed)sessionStorage.setItem(PREVIEW_SESSION,"1");else sessionStorage.removeItem(PREVIEW_SESSION)};

const renderModules=()=>{$("[data-module-grid]").innerHTML=modules.map(m=>{const locked=!creatorOverride&&m.week>1;return`<article class="module-card ${locked?'module-locked':''}"><div class="module-title-row"><p class="eyebrow">Week ${m.week}</p><span class="release-status">${locked?'Locked':'Available'}</span></div><h3>${m.title}</h3><p>${m.outcome}</p><button class="secondary" data-go="week-${m.week}">${locked?'View unlock details':`Open Week ${m.week}`}</button></article>`}).join("");bind()};
const refreshGateUI=()=>{$$('[data-stage]').forEach(card=>{const destination=card.dataset.stage,locked=Boolean(accessReason(destination));card.classList.toggle('stage-locked',locked);let badge=card.querySelector('.stage-lock');if(locked&&!badge){badge=document.createElement('span');badge.className='stage-lock';card.append(badge)}if(badge)badge.textContent=locked?'Locked until previous essential practice is complete':'Open'});};
const renderWeek=(m)=>{const panel=$(`[data-screen-panel="week-${m.week}"]`);if(m.week!==1){panel.innerHTML=`<header class="page-head week-hero"><p class="eyebrow">Week ${m.week}</p><h1>${m.title}</h1><p>${m.outcome}</p></header><article class="content-card"><p class="eyebrow">Opens in sequence</p><h2>Complete the prior week’s essential practice first.</h2><p>This week includes focused teaching, deliberate practice, a fictional clinical simulation, reflection, and a tool you can continue using.</p><button class="secondary" data-go="dashboard">Return to the roadmap</button></article>`;return}const essentialDone=['start','blind','simulation','profile'].filter(key=>completed.has(key)).length;panel.innerHTML=`
  <header class="page-head week-one-head week-hero"><div><p class="eyebrow">Week 1 · The Therapist Behind the Therapy</p><h1>${m.title}</h1><p>${m.outcome}</p></div><div class="week-status"><span>${essentialDone} of 4 essential stages complete</span><div><i style="width:${essentialDone*25}%"></i></div></div></header>
  <div class="week-callout"><strong>Your next step</strong><span>Begin with the first teaching lesson, then move through practice in order.</span><button class="primary" data-go="start">Continue training</button></div>
  <div class="experience-map" aria-label="Week 1 experience map">
    <article class="experience-step" data-stage="start"><b>1</b><div class="experience-icon">▶</div><div><p class="eyebrow">Watch</p><h2>Three teaching lessons</h2><p>${m.lessons.join(" · ")}</p><div class="lesson-chips">${m.lessons.map((x,i)=>`<button data-go="start">${i+1}. ${x}</button>`).join("")}</div></div><span class="time-pill">3 lessons</span></article>
    <article class="experience-step" data-stage="blind-spot"><b>2</b><div class="experience-icon">◎</div><div><p class="eyebrow">Train</p><h2>Clinical Blind Spot Lab</h2><p>Practice noticing what is observable, what may be an assumption, and what needs clarification.</p><button class="text-link" data-go="blind-spot">Open the training lab →</button></div><span class="time-pill">5 rounds</span></article>
    <article class="experience-step" data-stage="simulation-room"><b>3</b><div class="experience-icon">◫</div><div><p class="eyebrow">Experience</p><h2>Simulation Room: ${m.cases[0]}</h2><p>Step into the therapist role, choose a clinical direction, and see the fictional client respond.</p><button class="text-link" data-go="simulation-room">Enter the simulation →</button></div><span class="time-pill">Branching case</span></article>
    <article class="experience-step" data-stage="profile"><b>4</b><div class="experience-icon">✓</div><div><p class="eyebrow">Create</p><h2>${m.tool}</h2><p>Bring your observations, chosen directions, strengths, and one next practice target into a living profile.</p><button class="text-link" data-go="profile">Open my profile →</button></div><span class="time-pill">Living tool</span></article>
    <article class="experience-step optional"><b>5</b><div class="experience-icon">↻</div><div><p class="eyebrow">Practice More</p><h2>Practice Floor</h2><p>Return to brief fictional moments for optional, repeatable skill practice.</p><button class="text-link" data-go="practice-floor">Browse practice drills →</button></div><span class="time-pill">Optional</span></article>
  </div>`};
const activity=(kind,title,meta,open)=>`<article class="activity-card"><div class="activity-icon">${kind.includes("Video")||kind.includes("lesson")||kind.includes("Demonstration")?"▶":"✎"}</div><div><span>${kind}</span><h3>${title}</h3><p>${meta}</p></div>${open?'<button class="primary small" data-case-open>Start case</button>':'<button class="secondary small" disabled>Coming soon</button>'}</article>`;
const renderCapstone=()=>{$('[data-screen-panel="capstone"]').innerHTML=`<header class="page-head"><p class="eyebrow">Final capstone</p><h1>One Fictional Session, Several Decisions</h1><p>Practice five decisions across one fictional session: opening, maintaining process, intervention, rupture, and close.</p></header><article class="content-card"><h2>Jordan's simulated session</h2><p>Your response and clinical purpose will be saved at each stage. Clinical considerations stay hidden until all five decisions are attempted.</p><button class="primary" disabled>Opens after Week 4</button></article>`};

const renderStructureScreens=()=>{
  $('[data-screen-panel="blind-spot"]').innerHTML=`<button class="back-link" data-go="week-1">← Back to My Week</button><header class="page-head"><p class="eyebrow">Week 1 · Train</p><h1>Clinical Blind Spot Lab</h1><p>A five-round practice progression for deliberate attention—not a graded quiz.</p></header><div class="round-rail" data-blind-spot-rail><button>1 <span>The First Look</span></button><button>2 <span>Facts vs. Story</span></button><button>3 <span>Inner Monologue</span></button><button>4 <span>Practice P.A.U.S.E.</span></button><button>5 <span>Transfer Test</span></button></div><div data-blind-spot-player></div>`;
  $('[data-screen-panel="simulation-room"]').innerHTML=`<button class="back-link" data-go="week-1">← Back to My Week</button><header class="page-head"><p class="eyebrow">Week 1 · Experience</p><h1>Simulation Room</h1><p>The Advice Request</p></header><div data-simulation-player></div>`;
  $('[data-screen-panel="profile"]').innerHTML=`<header class="page-head profile-heading"><div><p class="eyebrow">A living development dashboard</p><h1>Clinical Confidence Profile</h1><p>Understand how you respond under clinical pressure, recognize what already supports your work, and choose deliberate practice targets from real evidence.</p></div><div class="profile-guardrail"><strong>Not a personality test</strong><span>No grades, diagnoses, or fixed clinician “type.” Everything remains editable.</span></div></header><div data-profile-app></div>`;
  $('[data-screen-panel="practice-floor"]').innerHTML=`<header class="page-head"><p class="eyebrow">Optional repeatable reps</p><h1>Practice Floor</h1><p>Brief fictional moments you can revisit without adding more required homework.</p></header><div class="drill-grid">${["The client asks for advice","The client goes silent","The client says ‘I don’t know’","The client gets emotional","The client says ‘You don’t get it’"].map((x,i)=>`<article><span>0${i+1}</span><h2>${x}</h2><p>Speak, type, or think through one grounded clinical move.</p><button class="secondary">Open 60-second drill</button></article>`).join("")}</div>`;
  $('[data-screen-panel="saved-practice"]').innerHTML=`<header class="page-head"><p class="eyebrow">Your activity history</p><h1>Saved Practice</h1><p>Revisit chosen paths, observations, notes, and retries without turning practice into a grade.</p></header><div class="empty-state"><span>◎</span><h2>No saved practice yet.</h2><p>Completed labs, simulations, and retries will appear here so you can review what you noticed and try again.</p><button class="primary" data-go="week-1">Go to My Week</button></div>`;
};

const profileOptions={
  focus:["Knowledge","Skill","Pressure","Support"],
  pressure:["Asked for a direct answer","Client goes silent","Client questions therapy","Strong emotion appears","Session loses direction","Time is running out","I may have missed something"],
  cues:["Breath gets shallow","Jaw or shoulders tighten","Thoughts speed up","Mind goes blank","I lean forward or rush","I lose track of the client’s words"],
  attention:["Find the right words","Explain or defend","Reassure quickly","Ask several questions","Solve the problem","Avoid making a mistake"],
  resets:["One quiet breath","Feel my feet","Return to the client’s last words","Slow my speaking pace","Name what I am noticing","Ask one clarifying question"],
  strengths:["Stays curious","Names uncertainty","Protects client autonomy","Notices relationship process","Checks safety and scope","Creates collaborative focus","Repairs openly","Uses supervision thoughtfully"]
};
const profilePills=(key,values)=>`<div class="profile-pills" data-profile-pills="${key}">${values.map(value=>`<button type="button" class="${profileState[key].has(value)?'selected':''}" data-value="${value}">${value}</button>`).join('')}</div>`;
const selectedList=(key,empty)=>{const values=[...profileState[key]];return values.length?`<ul>${values.map(value=>`<li>${esc(value)}</li>`).join('')}</ul>`:`<p class="map-empty">${empty}</p>`};
const practiceEvidence=()=>{const items=[];if(Object.keys(blindSpotAnswers).length)items.push({type:"Practice evidence",title:"Clinical Blind Spot Lab",detail:`${Object.keys(blindSpotAnswers).length} of 5 rounds attempted.`,source:"Blind Spot Lab"});const choices=simulationHistory.filter(item=>item.choiceLabel);if(choices.length)items.push({type:"Practice evidence",title:"Simulation decision path",detail:choices.map(item=>item.choiceLabel).join(" → "),source:"The Advice Request"});if(caseAnswers.retry)items.push({type:"Learner reflection",title:"A revised clinical response",detail:caseAnswers.retry,source:"Written case practice"});return [...items,...profileState.evidence]};
const renderProfile=()=>{const host=$('[data-profile-app]');if(!host)return;const evidence=practiceEvidence();const tab=(id,label)=>`<button type="button" role="tab" aria-selected="${profileTab===id}" class="${profileTab===id?'active':''}" data-profile-tab="${id}">${label}</button>`;host.innerHTML=`<div class="profile-nav" role="tablist" aria-label="Clinical Confidence Profile sections">${tab('snapshot','My Snapshot')}${tab('pressure','Pressure Map')}${tab('evidence','Evidence')}${tab('plan','Practice Plan')}</div><div class="profile-status-strip"><div><span>Practice evidence</span><strong>${evidence.filter(item=>item.type==='Practice evidence').length}</strong></div><div><span>Learner reflections</span><strong>${evidence.filter(item=>item.type!=='Practice evidence').length}</strong></div><div><span>Current target</span><strong>${profileState.target?'Active':'Not set'}</strong></div><p>Profile language reflects patterns you are exploring—not conclusions about competence.</p></div>${profileTab==='snapshot'?profileSnapshot(evidence):profileTab==='pressure'?profilePressure():profileTab==='evidence'?profileEvidence(evidence):profilePlan()}`;bindProfile()};
const profileSnapshot=(evidence)=>`<section class="profile-dashboard"><article class="profile-hero-card"><p class="eyebrow">Current development focus · Learner selected</p><h2>What deserves deliberate attention right now?</h2>${profilePills('focus',profileOptions.focus)}<p class="helper">Select any combination. A pressure gap is not automatically a knowledge or skill gap.</p></article><article><p class="eyebrow">Strengths in action · Learner selected</p><h2>What already helps you practice thoughtfully?</h2>${profilePills('strengths',profileOptions.strengths)}</article><article><p class="eyebrow">What practice is showing</p><h2>${evidence.length?`${evidence.length} pieces of evidence collected`:'Your profile will grow from your practice.'}</h2><ul class="profile-summary-list"><li><span>Blind Spot Lab</span><b>${Object.keys(blindSpotAnswers).length?`${Object.keys(blindSpotAnswers).length}/5 attempted`:'No evidence yet'}</b></li><li><span>Simulation decisions</span><b>${simulationHistory.filter(item=>item.choice).length?`${simulationHistory.filter(item=>item.choice).length} saved`:'No evidence yet'}</b></li><li><span>Written retry</span><b>${caseAnswers.retry?'Saved':'No evidence yet'}</b></li></ul></article><article><p class="eyebrow">My next practice target</p><h2>${profileState.target||'Choose one behavior small enough to notice.'}</h2><p>${profileState.target?'This target remains editable in your Practice Plan.':'Use your Pressure Map and practice evidence before setting it.'}</p><button class="text-link" data-open-plan>${profileState.target?'Edit my target':'Build my practice plan'} →</button></article><article class="profile-wide profile-meaning"><p class="eyebrow">A useful way to read this profile</p><div><strong>Notice</strong><span>What happened in the moment?</span><strong>Understand</strong><span>What pressure, need, or missing information shaped it?</span><strong>Practice</strong><span>What is one observable adjustment worth testing?</span><strong>Support</strong><span>What belongs in supervision, consultation, or further learning?</span></div></article></section>`;
const profilePressure=()=>`<section class="pressure-map"><div class="pressure-intro"><p class="eyebrow">Editable working map</p><h2>Notice pressure early enough to regain choice.</h2><p>This is not a diagnosis or a fixed pattern. It is a learner-authored map of situations, cues, and attention shifts worth noticing in practice.</p></div><article><span class="map-number">1</span><p class="eyebrow">Situations that add pressure</p><h2>What tends to put you on the spot?</h2><p class="helper">Choose every situation that feels relevant. Different situations may activate different responses.</p>${profilePills('pressure',profileOptions.pressure)}</article><article><span class="map-number">2</span><p class="eyebrow">Early cues</p><h2>How might you notice pressure arriving?</h2><p class="helper">Look for the earliest observable signal—not the moment you are already overwhelmed.</p>${profilePills('cues',profileOptions.cues)}</article><article><span class="map-number">3</span><p class="eyebrow">Attention pull</p><h2>Where does your attention tend to go?</h2><p class="helper">An attention pull is understandable. The goal is to notice when it moves you away from the client.</p>${profilePills('attention',profileOptions.attention)}</article><article><span class="map-number">4</span><p class="eyebrow">Create room for choice</p><h2>What could help you return to the client?</h2><p class="helper">Select strategies short enough to use without leaving the clinical moment.</p>${profilePills('resets',profileOptions.resets)}</article><article class="pressure-formula"><p class="eyebrow">My complete working map</p><h2>Everything you selected, kept visible.</h2><div class="map-summary-grid"><section><strong>Pressure situations</strong>${selectedList('pressure','Select one or more pressure situations above.')}</section><section><strong>Early cues</strong>${selectedList('cues','Select the cues you may notice first.')}</section><section><strong>Attention pulls</strong>${selectedList('attention','Select where your attention may go.')}</section><section><strong>Return strategies</strong>${selectedList('resets','Select a few realistic ways to return.')}</section></div><p class="map-reading"><strong>How to use this:</strong> Do not force every item into one chain. Before a practice attempt, choose one likely situation, one cue to watch for, and one return strategy to rehearse. Afterward, update the map with what actually happened.</p></article><article class="pressure-reflection"><p class="eyebrow">Look beneath the reaction</p><h2>What might the pressure response be trying to protect?</h2><p>Possibilities include avoiding harm, preserving the alliance, appearing competent, reducing uncertainty, or preventing a mistake. Understanding the protective intention can reduce shame without removing responsibility.</p><textarea data-profile-text="protecting" placeholder="I wonder if this response is trying to protect…">${esc(profileState.protecting)}</textarea></article><article class="pressure-reflection"><p class="eyebrow">Consider clinical impact</p><h2>What might the client experience when this pull takes over?</h2><p>Consider pacing, curiosity, emotional space, collaboration, autonomy, clarity, and whether important information might be missed.</p><textarea data-profile-text="impact" placeholder="The client might experience…">${esc(profileState.impact)}</textarea></article><article class="pressure-reflection pressure-exception"><p class="eyebrow">Find the exception</p><h2>When have you felt pressure and still responded with flexibility?</h2><p>Exceptions reveal conditions and skills that already support you. Name what you noticed, what helped, and what you did—not whether the session was perfect.</p><textarea data-profile-text="exception" placeholder="One time I stayed connected despite uncertainty was… What helped was…">${esc(profileState.exception)}</textarea></article><aside class="profile-insight"><p class="eyebrow">A reminder worth keeping</p><h3>Having several pressure responses does not mean you are less capable.</h3><p>It may mean different clinical moments pull your attention in different directions. Your useful task is not to eliminate pressure; it is to recognize it sooner, stay within scope, and recover choice.</p></aside></section>`;
const profileEvidence=(evidence)=>`<section class="evidence-section"><div class="section-heading"><div><p class="eyebrow">Evidence, not self-judgment</p><h2>Build a record of what you actually practiced.</h2></div><p>Keep observations separate from interpretation. Add only fictional or appropriately generalized moments.</p></div><div class="evidence-timeline">${evidence.length?evidence.map((item,index)=>`<article><span>${String(index+1).padStart(2,'0')}</span><div><p class="eyebrow">${item.type} · ${item.source}</p><h3>${esc(item.title)}</h3><p>${esc(item.detail)}</p></div></article>`).join(''):`<div class="empty-profile"><h3>No evidence saved yet.</h3><p>Complete a Blind Spot round, make a Simulation Room decision, or add a generalized learning moment below.</p></div>`}</div><form class="evidence-form" data-evidence-form><p class="eyebrow">Add a generalized learning moment</p><h2>What do you want your future self to remember?</h2><label>Moment or context<input name="title" required placeholder="Example: Client asked me to make the decision"></label><label>What I observed<textarea name="detail" required placeholder="Describe what you noticed without including identifying client information…"></textarea></label><label>What this may be evidence of<input name="meaning" required placeholder="Example: I can slow down before offering reassurance"></label><button class="primary" type="submit">Add to my evidence</button><p class="save-note" role="status"></p></form></section>`;
const profilePlan=()=>`<section class="plan-grid"><article class="plan-target"><p class="eyebrow">One observable target</p><h2>What will you practice—not merely “be better at”?</h2><label>For the next seven days, I will…<textarea data-profile-text="target" placeholder="Example: Ask one clarifying question before moving toward reassurance.">${esc(profileState.target)}</textarea></label><p class="helper">Choose a behavior you can recognize in a real session or fictional practice attempt.</p></article><article><p class="eyebrow">Practice independently</p><h2>What can you safely rehearse on your own?</h2><textarea data-profile-text="independent" placeholder="A phrase, pause, question, or decision process…">${esc(profileState.independent)}</textarea></article><article><p class="eyebrow">Bring support in</p><h2>What needs supervision, consultation, or further training?</h2><textarea data-profile-text="support" placeholder="Name the uncertainty, scope question, or context you do not want to hold alone…">${esc(profileState.support)}</textarea></article><article><p class="eyebrow">Supervision agenda</p><h2>Turn uncertainty into one useful question.</h2><textarea data-profile-text="supervision" placeholder="Example: How can I assess safety without making every decision-focused conversation feel like a checklist?">${esc(profileState.supervision)}</textarea></article><article class="profile-wide reset-plan"><p class="eyebrow">My in-session reset plan</p><h2>When pressure shows up, I want something usable—not inspirational.</h2><div class="reset-sentence"><span>When I notice</span><strong>${[...profileState.cues][0]||'my early cue'}</strong><span>and my attention moves toward</span><strong>${[...profileState.attention][0]||'my usual pull'}</strong><span>I will</span><strong>${[...profileState.resets][0]||'use one short reset'}</strong><span>so I can return to the client.</span></div></article><div class="profile-actions profile-wide"><button class="primary" data-save-profile>Save this plan</button><button class="secondary" data-print-profile>Print / save as PDF</button><p class="save-note" role="status"></p></div></section>`;
const bindProfile=()=>{$$('[data-profile-pills] button').forEach(button=>button.onclick=()=>{const key=button.parentElement.dataset.profilePills,value=button.dataset.value;if(profileState[key].has(value))profileState[key].delete(value);else profileState[key].add(value);renderProfile()});$('[data-open-plan]')?.addEventListener('click',()=>{profileTab='plan';renderProfile();scrollTo({top:0,behavior:'smooth'})});$$('[data-profile-text]').forEach(field=>field.oninput=()=>profileState[field.dataset.profileText]=field.value);$('[data-evidence-form]')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);profileState.evidence.unshift({type:'Learner reflection',source:'Generalized learning moment',title:String(data.get('title')||''),detail:`${data.get('detail')} Working meaning: ${data.get('meaning')}`});renderProfile()});$('[data-save-profile]')?.addEventListener('click',event=>{profileState.target=$('[data-profile-text="target"]').value.trim();markComplete('profile');event.currentTarget.parentElement.querySelector('.save-note').textContent='Saved for this session.'});$('[data-print-profile]')?.addEventListener('click',()=>window.print())};

const simulationClips={
  J00:{beat:0,title:"Opening",duration:"~22 sec",script:"I had another fight with my partner. And we always end up in the same place. I’m exhausted. I’ve talked about it with everybody, and nobody really says anything useful. You’re the therapist, so… can you just tell me? Should I break up with them?",options:[{label:"Explore the dilemma",detail:"Stay with what makes the decision difficult.",next:"J11"},{label:"Clarify autonomy",detail:"Acknowledge the request without taking over the choice.",next:"J12"},{label:"Choose an urgent focus",detail:"Ask what would feel most useful today.",next:"J13"}]},
  J11:{beat:1,title:"Explore the dilemma",duration:"~17 sec",script:"I don't know. It's like, when things are good, they're really good. And then we have another argument, and I think, why am I still doing this? I keep going back and forth.",next:"J20"},
  J12:{beat:1,title:"Autonomy",duration:"~18 sec",script:"I get that it's my decision. I do. But that's kind of why I'm asking. I make decisions all day, and I just wanted someone who knows what they're doing to tell me what makes sense.",next:"J20"},
  J13:{beat:1,title:"Urgent focus",duration:"~17 sec",script:"Honestly? I'm just tired. I don't even know whether I want to talk about the fight or the fact that I can't make a decision. I just want to stop going in circles.",next:"J20"},
  J20:{beat:1,title:"Rejoin 1",duration:"~14 sec",script:"And the annoying part is, I keep thinking about whether I'm going to regret whatever I decide. I picture leaving and regretting it. Then I picture staying and regretting that too.",options:[{label:"Explore fear of regret",detail:"Stay with the anticipated loss on both sides.",next:"J21"},{label:"Explore the prior pattern",detail:"Ask how second-guessing shows up in other decisions.",next:"J22"},{label:"Check safety and freedom",detail:"Assess whether Jordan feels safe and able to choose.",next:"J23"}]},
  J21:{beat:2,title:"Fear of regret",duration:"~16 sec",script:"I think I'd feel like I'd failed. Like I should have worked harder to make things better. But if I stay, I worry I'm just wasting more time.",next:"J30"},
  J22:{beat:2,title:"Prior pattern",duration:"~16 sec",script:"I do this with other things too. Even little decisions. I ask everybody what they think, and then I still second-guess myself. It's exhausting.",next:"J30"},
  J23:{beat:2,title:"Safety check",duration:"~17 sec",script:"I don't feel afraid of my partner, if that's what you're asking. We argue, but I can leave or say no. I just get overwhelmed trying to figure out what I want. And I know we haven't really talked much about the arguments yet.",next:"J30"},
  J30:{beat:2,title:"Rejoin 2",duration:"~13 sec",script:"I think part of me wants someone else to make the call, because then if it goes badly, I won't feel like it was all on me.",options:[{label:"Reflect the pressure",detail:"Name how much responsibility Jordan is carrying.",next:"J31"},{label:"Explore what the decision means",detail:"Stay with the meaning of leaving and staying.",next:"J32"},{label:"Identify the support Jordan needs",detail:"Separate Jordan's voice from everyone else's opinions.",next:"J33"}]},
  J31:{beat:3,title:"Reflect pressure",duration:"~18 sec",script:"Yeah. I'm carrying so much of it in my head. And then I come here, and I feel like I should have an answer by the end of the hour. I know that's probably not how it works, but that's what I want.",next:"J40"},
  J32:{beat:3,title:"Explore meaning",duration:"~16 sec",script:"Leaving would mean admitting something I hoped would work… isn't working the way I wanted. Staying means hoping something changes. I don't really know which one I'm more scared of.",next:"J40"},
  J33:{beat:3,title:"Support",duration:"~16 sec",script:"Maybe I need help sorting out what actually matters to me, instead of collecting opinions. I can hear everybody else's voice when I try to decide. Mine gets really quiet.",next:"J40"},
  J40:{beat:3,title:"Rejoin 3",duration:"~12 sec",script:"I don't expect you to magically fix my relationship. I guess I just want to leave today feeling like there's a way to think about it that isn't this whole spiral.",options:[{label:"Choose one small next step",detail:"Collaborate on something manageable before the next session.",next:"J41"},{label:"Clarify what Jordan needs to understand",detail:"Identify the information that would support a decision.",next:"J42"},{label:"Summarize and check",detail:"Offer a formulation and invite Jordan to correct it.",next:"J43"}]},
  J41:{beat:4,title:"Next step",duration:"~17 sec",script:"Okay. Something small would help. I don't think I'm ready to make the decision today, but maybe I can at least figure out what I need to understand before I do.",next:"J50"},
  J42:{beat:4,title:"What to understand",duration:"~17 sec",script:"I think I need to understand why I keep ignoring what matters to me when someone else has a strong opinion. I don't know if that's what's happening here, but it might be part of it.",next:"J50"},
  J43:{beat:4,title:"Summary check",duration:"~16 sec",script:"Yeah, that sounds close. I think it's less about getting someone to tell me the right answer and more about not trusting myself with either answer.",next:"J50"},
  J50:{beat:5,title:"Final recording prompt",duration:"~18 sec",script:"Can I ask you something before we finish? What do you think I should actually do between now and next time? Because I don't want to just leave and spend another week going in circles.",final:true}
};
const decisionNumber=()=>Math.min(4,simulationHistory.filter(item=>item.choice).length+1);
const renderSimulation=()=>{const host=$('[data-simulation-player]');if(!host)return;const clip=simulationClips[simulationNode];const progress=Math.min(4,simulationHistory.filter(item=>item.choice).length);host.innerHTML=`<div class="simulation-shell"><div class="simulation-top"><span>${clip.final?'Final response':`Decision point ${decisionNumber()} of 4`} · ${clip.duration}</span><div>${[0,1,2,3].map(index=>`<i class="${index<progress?'active':''}"></i>`).join('')}</div></div><div class="simulation-video"><span>Jordan · Fictional client</span><button class="video-play" type="button" data-video-play aria-label="Play client video">▶</button><strong>${clip.title}</strong><small>Client video · ${clip.duration}</small></div><div class="script-drawer"><button type="button" data-script-toggle aria-expanded="false">View transcript</button><blockquote hidden data-script>“${clip.script}”</blockquote></div>${clip.options?`<h2>Where would you take the conversation?</h2><p class="decision-help">Choose a clinical direction. Jordan’s next response changes based on your selection.</p><div class="direction-grid">${clip.options.map(option=>`<button data-simulation-choice="${option.next}"><strong>${option.label}</strong><span>${option.detail}</span></button>`).join('')}</div>`:clip.final?`<div class="simulation-reflection"><p class="eyebrow">Your turn</p><h2>Respond to Jordan in your own words.</h2><label>Your response<textarea data-simulation-note placeholder="Type what you would say, or use this space to plan a spoken response…"></textarea></label><label>What is the clinical purpose of your response?<textarea data-simulation-purpose placeholder="Explain what you want your response to open up or protect…"></textarea></label><p class="form-error" role="alert"></p><button class="primary" data-simulation-complete>Complete and review my path</button></div>`:`<div class="simulation-reflection"><p class="eyebrow">Jordan responded</p><h2>Break down what happened before continuing.</h2><label>What did Jordan’s response tell you?<textarea data-simulation-note placeholder="Notice new information, emotion, relationship process, or uncertainty…"></textarea></label><label>What would you attend to next?<textarea data-simulation-purpose placeholder="Name the purpose of your next clinical move…"></textarea></label><p class="form-error" role="alert"></p><button class="primary" data-simulation-continue>Save reflection and continue</button></div>`}<div class="simulation-history-bar"><button class="text-link" type="button" data-simulation-history>What happened so far (${simulationHistory.length})</button><button class="text-link" type="button" data-simulation-restart>Restart simulation</button></div><div class="path-history" hidden data-path-history>${simulationHistory.length?simulationHistory.map((item,index)=>`<div><span>${index+1}</span><p><strong>${item.node}${item.choice?` → ${item.choiceLabel}`:''}</strong>${item.note?`<br>${esc(item.note)}`:''}</p></div>`).join(''):'<p>No decisions saved yet.</p>'}</div></div>`;
  $('[data-video-play]').onclick=event=>{event.currentTarget.textContent=event.currentTarget.textContent==='▶'?'❚❚':'▶'};
  $('[data-script-toggle]').onclick=event=>{const transcript=$('[data-script]');transcript.hidden=!transcript.hidden;event.currentTarget.setAttribute('aria-expanded',String(!transcript.hidden));event.currentTarget.textContent=transcript.hidden?'View transcript':'Hide transcript'};
  $$('[data-simulation-choice]').forEach(button=>button.onclick=()=>{const option=clip.options.find(item=>item.next===button.dataset.simulationChoice);simulationHistory.push({node:simulationNode,choice:option.next,choiceLabel:option.label});simulationNode=option.next;renderSimulation();scrollTo({top:0,behavior:'smooth'})});
  $('[data-simulation-continue]')?.addEventListener('click',()=>{const note=$('[data-simulation-note]').value.trim(),purpose=$('[data-simulation-purpose]').value.trim();if(note.length<3||purpose.length<3){$('.form-error').textContent='Add a brief observation and clinical purpose before continuing.';return}simulationHistory.push({node:simulationNode,note,purpose});simulationNode=clip.next;renderSimulation();scrollTo({top:0,behavior:'smooth'})});
  $('[data-simulation-complete]')?.addEventListener('click',()=>{const note=$('[data-simulation-note]').value.trim(),purpose=$('[data-simulation-purpose]').value.trim();if(note.length<3||purpose.length<3){$('.form-error').textContent='Add your response and its clinical purpose before reviewing your path.';return}simulationHistory.push({node:simulationNode,note,purpose});markComplete('simulation');host.innerHTML=`<article class="completion-card"><span class="check">✓</span><p class="eyebrow">Simulation complete</p><h2>You shaped the conversation through four clinical decisions.</h2><p>The goal is not a perfect route. Review what each choice opened up, what Jordan revealed, and how your reasoning developed.</p><div class="simulation-review">${simulationHistory.map((item,index)=>`<div><span>${index+1}</span><p><strong>${item.node}${item.choiceLabel?` · ${item.choiceLabel}`:''}</strong>${item.note?`<br>${esc(item.note)}<br><em>Purpose: ${esc(item.purpose)}</em>`:''}</p></div>`).join('')}</div><button class="secondary" data-simulation-restart>Try another path</button><button class="primary" data-go="week-1">Return to My Week</button></article>`;bind();$('[data-simulation-restart]').onclick=restartSimulation});
  $('[data-simulation-history]').onclick=()=>{const history=$('[data-path-history]');history.hidden=!history.hidden};
  $('[data-simulation-restart]').onclick=restartSimulation;
};
function restartSimulation(){simulationNode='J00';simulationHistory.splice(0);renderSimulation();scrollTo({top:0,behavior:'smooth'})}

const blindSpotRounds=[
  {label:"The First Look",title:"What stood out?",body:"Watch once, then capture what you remember noticing before any teaching appears.",prompt:"Your observation",placeholder:"Write a brief private observation…",choices:["Client words","Tone / pacing","Emotion","What I assumed"]},
  {label:"Facts vs. Story",title:"What did you observe—and what did you infer?",body:"Separate what the fictional client directly reported from the meaning you may have added.",prompt:"Choose one phrase and explain your tag",placeholder:"What was observable? What might be a hypothesis?",choices:["Observed","Hypothesis","Need to clarify"]},
  {label:"Inner Monologue",title:"Where did your attention go?",body:"Notice the simulated pressure thought that could pull attention away from the client.",prompt:"What would help you return to the client?",placeholder:"Name the pressure and one way you would redirect your attention…",choices:["What should I say?","I need to fix this","They expect me to help","None / other"]},
  {label:"Practice P.A.U.S.E.",title:"Choose one grounded next move",body:"Use P.A.U.S.E. as a compact stepper: Pause, Attend, Use, Say, Explore.",prompt:"Write what you would say",placeholder:"Try one natural sentence—not a perfect script…",choices:["Explore what makes saying no difficult","Clarify what ‘supposed to’ means","Validate and collaborate"]},
  {label:"Transfer Test",title:"Try it with less scaffolding",body:"Apply the same attention skills to a new fictional client moment, then name one intentional adjustment.",prompt:"Your response and adjustment",placeholder:"What would you say, and what did you intentionally adjust?",choices:[]}
];
const saveBlindSpotAnswer=()=>{const field=$('[data-blind-spot-response]');if(field)blindSpotAnswers[blindSpotRound]=field.value.trim()};
const renderBlindSpot=()=>{const host=$('[data-blind-spot-player]');if(!host)return;$$('[data-blind-spot-rail] button').forEach((button,index)=>button.classList.toggle('active',index+1===blindSpotRound));const round=blindSpotRounds[blindSpotRound-1];if(blindSpotRound>5){host.innerHTML=`<article class="completion-card"><span class="check">✓</span><p class="eyebrow">Blind Spot Lab complete</p><h2>You practiced noticing before reacting.</h2><p>Your five responses can now inform your Clinical Confidence Profile.</p><div class="review-sequence"><div><span>First Look</span><p>${esc(blindSpotAnswers[1])}</p></div><div><span>P.A.U.S.E.</span><p>${esc(blindSpotAnswers[4])}</p></div><div><span>Transfer Test</span><p>${esc(blindSpotAnswers[5])}</p></div></div><button class="secondary" data-blind-spot-restart>Try the lab again</button><button class="primary" data-go="week-1">Return to My Week</button></article>`;bind();$('[data-blind-spot-restart]').onclick=()=>{blindSpotRound=1;Object.keys(blindSpotAnswers).forEach(key=>delete blindSpotAnswers[key]);renderBlindSpot()};return}host.innerHTML=`<article class="focused-practice"><div class="practice-media"><span>Fictional client clip</span><strong>Client video</strong><small>Listen for words, tone, pacing, and emotion.</small></div><div><p class="eyebrow">Round ${blindSpotRound} · ${round.label}</p><h2>${round.title}</h2><p>${round.body}</p>${round.choices.length?`<div class="choice-pills">${round.choices.map(choice=>`<button type="button">${choice}</button>`).join("")}</div>`:""}<label>${round.prompt}<textarea data-blind-spot-response placeholder="${round.placeholder}">${esc(blindSpotAnswers[blindSpotRound]||"")}</textarea></label><p class="form-error" role="alert"></p><div class="round-actions">${blindSpotRound>1?'<button class="secondary" data-blind-spot-back>Back</button>':''}<button class="primary" data-blind-spot-next>${blindSpotRound===5?'Complete the lab':'Save and continue'}</button></div><p class="save-note" role="status">Your response is saved as you continue.</p></div></article>`;$$('.choice-pills button',host).forEach(button=>button.onclick=()=>button.classList.toggle('selected'));$('[data-blind-spot-next]').onclick=()=>{saveBlindSpotAnswer();if((blindSpotAnswers[blindSpotRound]||'').length<3){$('.form-error',host).textContent='Add a brief response before continuing.';return}if(blindSpotRound===5)markComplete('blind');blindSpotRound++;renderBlindSpot();scrollTo({top:0,behavior:'smooth'})};$('[data-blind-spot-back]')?.addEventListener('click',()=>{saveBlindSpotAnswer();blindSpotRound--;renderBlindSpot();scrollTo({top:0,behavior:'smooth'})})};

const show=(name,remember=true)=>{const reason=accessReason(name);if(reason){openGate(name,reason);return}const current=$('.screen.active')?.dataset.screenPanel;if(remember&&current&&current!==name)screenHistory.push(current);$$(".screen").forEach(x=>x.classList.toggle("active",x.dataset.screenPanel===name));$$('.side-link').forEach(x=>x.classList.toggle('active',x.dataset.screen===name));const panel=$(`[data-screen-panel="${name}"]`);if(name!=="dashboard"&&panel&&!panel.querySelector(':scope > .back-link')){const back=document.createElement('button');back.type='button';back.className='back-link page-back';back.textContent='← Go back';panel.prepend(back)}const back=panel?.querySelector(':scope > .page-back');if(back)back.onclick=()=>show(screenHistory.pop()||(name.startsWith('week-')?'dashboard':'week-1'),false);$(".course-sidebar").classList.remove("open");$("[data-menu]").setAttribute("aria-expanded","false");scrollTo({top:0,behavior:"smooth"});};

const fields=(names)=>names.map(([key,label,placeholder])=>`<label>${label}<textarea data-case-field="${key}" placeholder="${placeholder||"Write your response…"}">${esc(caseAnswers[key]||"")}</textarea></label>`).join("");
const saveFields=()=>{$$("[data-case-field]").forEach(x=>caseAnswers[x.dataset.caseField]=x.value.trim());};
const meaningful=(keys)=>keys.every(k=>(caseAnswers[k]||"").trim().length>2);
const renderCase=()=>{const host=$("[data-case-player]");$$(".case-progress i").forEach((x,i)=>x.classList.toggle("active",i<caseStep));$("[data-case-step]").textContent=caseStep;
  if(caseStep===1)host.innerHTML=`<article class="dialogue-card"><p class="eyebrow">Meet the client</p><h2>Jordan, 29</h2><p>During a third appointment, Jordan describes another argument with their partner. Jordan looks exhausted and says the relationship has been draining for months. No immediate safety concerns have been assessed yet.</p><blockquote>“Just tell me what to do. You’re the therapist. Should I break up with them?”</blockquote></article><article class="response-card"><h2>Make your first clinical decision</h2>${fields([["noticed","What is the most important thing you noticed?"],["first","What would you actually say next?"],["why","Why would you choose that response?"],["info","What additional information might be useful?"]])}<p class="form-error" role="alert"></p><button class="primary" data-case-next>Save & reveal what happens next</button></article>`;
  if(caseStep===2)host.innerHTML=`<article class="reveal-card"><p class="eyebrow">New client information</p><h2>The situation changes.</h2><blockquote>Jordan says, “I’m paying you because I can’t make decisions on my own.”</blockquote></article><article class="response-card"><h2>Reconsider your response</h2>${fields([["changed","What changed with this new information?"],["adjust","Would you keep or adjust your original response? Why?"],["next","What would you say or do next?"],["limits","Is there any assessment, safety, consultation, or scope consideration?"]])}<p class="form-error" role="alert"></p><button class="primary" data-case-next>Save & see the clinical breakdown</button></article>`;
  if(caseStep===3)host.innerHTML=`<article class="breakdown-card"><p class="eyebrow">Clinical reasoning breakdown</p><h2>Compare purposes—not perfect sentences.</h2><div class="less-useful"><strong>A less useful first move</strong><p>“Yes, you should probably leave.” It substitutes therapist preference for collaborative exploration and bypasses safety and context.</p></div><div class="option-grid"><div><strong>Defensible response A</strong><p>“I can help you sort through it, but I don’t want to make a decision that belongs to you. What has been making staying or leaving so hard?”</p></div><div><strong>Defensible response B</strong><p>“Before we weigh options, I want to understand whether you feel safe and free to make decisions in this relationship.”</p></div></div><p><strong>Reasoning and boundary:</strong> Either can fit, depending on history and risk. The safer opening moves toward assessment when coercion or abuse is possible. Ask; do not presume.</p><div class="coach"><strong>Retry cue</strong><p>Replace reassurance or advice with a question that clarifies the client's priorities while acknowledging the pressure.</p></div><button class="primary" data-case-next>Reflect and retry</button></article>`;
  if(caseStep===4)host.innerHTML=`<article class="response-card"><p class="eyebrow">Reflection and retry</p><h2>What will you keep—and what will you change?</h2><div class="your-first"><span>Your original response</span><p>${esc(caseAnswers.first)}</p></div>${fields([["keep","Which parts of your initial response would you keep?"],["change","What is one specific adjustment you would make?"],["retry","How would your revised response sound out loud?"],["learned","What did you learn about your clinical reasoning?"]])}<p class="form-error" role="alert"></p><button class="primary" data-case-next>Save final retry</button></article>`;
  if(caseStep===5)host.innerHTML=`<article class="completion-card"><span class="check">✓</span><p class="eyebrow">Case complete</p><h2>You practiced adapting—not performing certainty.</h2><p>Your original response, revised reasoning, model comparison, and final retry would now be saved privately to your course account.</p><div class="review-sequence"><div><span>First response</span><p>${esc(caseAnswers.first)}</p></div><div><span>After the reveal</span><p>${esc(caseAnswers.next)}</p></div><div><span>Final retry</span><p>${esc(caseAnswers.retry)}</p></div></div><button class="secondary" data-case-restart>Start a new attempt</button><button class="primary" data-go="week-1">Return to Week 1</button></article>`;
  bind();};
const bind=()=>{$$("[data-go]").forEach(x=>x.onclick=()=>show(x.dataset.go));$$('[data-case-open]').forEach(x=>x.onclick=()=>{caseStep=1;renderCase();show('case-advice')});$('[data-case-next]')?.addEventListener('click',()=>{saveFields();const needed=caseStep===1?["noticed","first","why","info"]:caseStep===2?["changed","adjust","next","limits"]:caseStep===4?["keep","change","retry","learned"]:[];if(needed.length&&!meaningful(needed)){$('.form-error').textContent='Add a meaningful attempt to each response before continuing.';return;}caseStep++;renderCase();scrollTo({top:0,behavior:'smooth'})});$('[data-case-restart]')?.addEventListener('click',()=>{Object.keys(caseAnswers).forEach(k=>delete caseAnswers[k]);caseStep=1;renderCase()});};

renderModules();modules.forEach(renderWeek);renderCapstone();renderStructureScreens();renderProfile();renderBlindSpot();renderSimulation();renderCase();bind();refreshGateUI();
document.addEventListener('click',event=>{const button=event.target.closest('[data-profile-tab]');if(!button)return;event.preventDefault();profileTab=button.dataset.profileTab;renderProfile();$('[data-profile-app]')?.scrollIntoView({behavior:'smooth',block:'start'})});
$('[data-gate-form]').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);if(String(data.get('passcode')||'')!==PREVIEW_PASSWORD){$('[data-gate-error]').textContent='That course owner passcode does not match.';return}creatorOverride=true;sessionStorage.setItem(OVERRIDE_KEY,'1');const target=pendingGate;pendingGate=null;$('[data-gate-dialog]').close();event.currentTarget.reset();renderModules();modules.forEach(renderWeek);bind();refreshGateUI();if(target)show(target)});
$('[data-gate-cancel]').onclick=()=>{$('[data-gate-dialog]').close();pendingGate=null};
$('[data-preview-login-form]').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const allowed=String(data.get('email')||'').trim().toLowerCase()===PREVIEW_EMAIL&&String(data.get('password')||'')===PREVIEW_PASSWORD;if(!allowed){$('[data-preview-login-error]').textContent='That email or password does not match.';return}$('[data-preview-login-error]').textContent='';setPreviewAccess(true)});
$('[data-preview-signout]').onclick=()=>{setPreviewAccess(false);$('[data-preview-login-form]').reset()};
setPreviewAccess(sessionStorage.getItem(PREVIEW_SESSION)==='1');
const requestedScreen=new URLSearchParams(location.search).get('screen');if(requestedScreen&&$(`[data-screen-panel="${requestedScreen}"]`))show(requestedScreen);
$('[data-menu]').onclick=()=>{const side=$('.course-sidebar');side.classList.toggle('open');$('[data-menu]').setAttribute('aria-expanded',String(side.classList.contains('open')))};
$$('[data-demo-save]').forEach(button=>button.onclick=e=>{const reflection=e.currentTarget.closest('.content-card')?.querySelector('textarea');const note=e.currentTarget.nextElementSibling;if(!reflection?.value.trim()){note.textContent='Add one specific moment before continuing.';return}markComplete('start');note.textContent='Saved. The Clinical Blind Spot Lab is now open.'});
